// src/main.js - Galaxy Outlast Main Entry Point
import './styles/main.css';

// 1. Boot Error Reporter
(function(){
        var shown=!1;
        function show(tag,msg){
          try{
            var box=document.getElementById("__boot_err");
            if(!box){
              box=document.createElement("div");
              box.id="__boot_err";
              box.style.cssText="position:fixed;left:4px;right:4px;bottom:4px;z-index:2147483647;background:#5a0011;color:#ffd7de;font:12px/1.4 monospace;padding:8px 10px;border-radius:6px;white-space:pre-wrap;max-height:45%;overflow:auto;box-shadow:0 0 12px #000;";
              (document.body||document.documentElement).appendChild(box);
              box.addEventListener("click",function(){box.parentNode&&box.parentNode.removeChild(box);});
            }
            if(shown&&tag!=="BOOT")return;
            shown=!0;
            box.textContent="GALAXY OUTLAST "+tag+" (build v1.33):\n"+String(msg).substring(0,800)+"\n\n(tap to dismiss)";
          }catch(e){}
        }
        window.__showFatal=function(msg){show("ERROR",msg);};
        window.__bootStage="page-loaded";
        setTimeout(function(){
          try{
            if(!window.__bootDone){
              var bs=document.getElementById("btn-start");
              show("STARTUP STALL","stage="+window.__bootStage+
                " | launchWired="+(!!(bs&&bs.onclick))+
                " | view="+window.innerWidth+"x"+window.innerHeight+
                " dpr="+window.devicePixelRatio);
            }
          }catch(e){}
        },3000);
        window.addEventListener("error",function(e){
          var r=e&&(e.error||e.message);
          show("ERROR",r&&((r.stack||r.message)||String(r))||String(e));
        });
        window.addEventListener("unhandledrejection",function(e){
          var r=e&&e.reason,s=(r&&(r.stack||r.message))||String(r);
          if(/orientation\.lock|ServiceWorkerRegistration|serviceWorker/i.test(s))return;
          show("ASYNC ERROR",s);
        });
      })();

// 2. Service Worker & Cache Cleanup
if ('serviceWorker' in navigator) {
        navigator.serviceWorker.getRegistrations().then(registrations => {
          for (let registration of registrations) {
            registration.unregister();
          }
        });
        if ('caches' in window) {
          caches.keys().then(names => {
            for (let name of names) {
              caches.delete(name);
            }
          });
        }
      }

// 3. Game Core Modules
import './game/bosses.js';
import './game/weapons.js';
import './game/audio.js';
import './game/state.js';
import './game/render.js';
import './game/diagnostics.js';

